int dvb_diseqc_send_master_cmd(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int rc;
	int i;

	if ((d->msg[0] & 0xc0) != 0x40)
		return -EINVAL;

	if (d->msg_len > 6)
		return -EINVAL;

	if (d->msg_len < 2)
		return -EINVAL;

	if (fe->ops.send_diseqc_master_cmd)
		rc = fe->ops.send_diseqc_master_cmd(fe, d);
	else
		rc = -EOPNOTSUPP;

	if (rc != 0)
		return rc;

	return 0;
}

int dvb_diseqc_send_master_msg(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int i;
	struct dvb_frontend_private *priv = fe->demodulator_priv;
	struct dvb_diseqc_slave_reply *r = &priv->diseqc_slave_reply;

	if (d->msg[0] < 0x30 || d->msg[0] > 0x3F)
		return -EINVAL;

	if (d->msg[0] >= 0x38)
		d->msg[0] += 0x02;

	memcpy(r->msg, d->msg, sizeof(r->msg));
	r->msg_len = d->msg_len;

	if (fe->ops.send_diseqc_master_cmd)
		return fe->ops.send_diseqc_master_cmd(fe, d);

	return -EOPNOTSUPP;
}

int dvb_diseqc_send_master_msg(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int i, rc;
	struct dvb_frontend_private *fepriv = fe->demodulator_priv;

	if (d->msg[0] < 3 || d->msg[0] > 6) {
		dprintk(1, "invalid message length %d\n", d->msg[0]);
		return -EINVAL;
	}

	dprintk(1, "sending DiSEqC: %*ph\n", d->msg[0], d->msg);

	memcpy(fepriv->diseqc.msg, d->msg, d->msg[0]);
	fepriv->diseqc.length = d->msg[0];

	if (fe->ops.set_tone)
		fe->ops.set_tone(fe, 0);

	if (fe->ops.set_voltage)
		fe->ops.set_voltage(fe, SEC_VOLTAGE_13);

	msleep(100);

	if (fe->ops.diseqc_send_master_cmd) {
		rc = fe->ops.diseqc_send_master_cmd(fe, &fepriv->diseqc);
		if (rc < 0)
			return rc;
	}

	msleep(50);

	if (fe->ops.set_voltage)
		fe->ops.set_voltage(fe, SEC_VOLTAGE_18);

	return 0;
}

int dvb_diseqc_send_master_cmd(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int i;
	int rc = 0;

	if (d->msg[0] > 6) {
		return -EINVAL;
	}

	if (dvb_debug >= 4) {
		printk(KERN_DEBUG "DiSEqC: sending master cmd:");
		for (i = 0; i < d->msg[0] + 1; i++)
			printk(KERN_DEBUG " %02x", d->msg[i]);
		printk(KERN_DEBUG "\n");
	}

	if (fe->ops.set_toneburst)
		rc = fe->ops.set_toneburst(fe, d->msg[0] == 3 ? DVB_TONEBURST_A : DVB_TONEBURST_B);

	if (rc < 0)
		return rc;

	if (fe->ops.diseqc_master_cmd)
		rc = fe->ops.diseqc_master_cmd(fe, d);

	if (rc < 0)
		return rc;

	/* wait for message to be sent */
	msleep(20);

	return 0;
}

int send_diseqc_message(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int result = 0;

	if (d->msg_len < 1 || d->msg_len > DVB_DISEQC_MAX_MSG_LEN) {
		return -EINVAL;
	}

	if (debug) {
		int i;
		printk(KERN_DEBUG "DiSEqC message: ");
		for (i = 0; i < d->msg_len; i++) {
			printk(KERN_CONT "%02x ", d->msg[i]);
		}
		printk(KERN_CONT "\n");
	}

	d->msg[0] |= (1 << 6); /* Set the START bit */
	d->cmd_len = d->msg_len;

	if (d->msg[0] & (1 << 7)) {
		d->tx_toneburst = DISEQC_TONEBURST_A;
	} else {
		d->tx_toneburst = DISEQC_TONEBURST_B;
	}

	if (fe->ops.set_tone)
		fe->ops.set_tone(fe, SEC_TONE_ON);

	msleep(10); /* Allow voltage stabilization on LNB */

	result = fe->ops.send_diseqc_msg(fe, d);

	msleep((d->msg_len * 10) + (d->tx_toneburst == DISEQC_TONEBURST_A ? 50 : 0));

	return result;
}
